const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '1/3 < 1/2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(70, Math.min(110, W * 0.14));
    var x0 = margin;
    var x1 = W - margin;
    var y = Math.round(H * 0.56);
    var span = x1 - x0;
    function tx(v) { return x0 + v * span; }
    var main = '#1f3a5f';
    var accent = '#c0392b';
    var axis = visualSdk.arrow(x0 - 16, y, x1 + 22, y, {});
    var ticks = [];
    var vals = [0, 1 / 3, 1 / 2, 1];
    for (var i = 0; i < vals.length; i++) {
      var xv = tx(vals[i]);
      var half = (i === 0 || i === 3) ? 9 : 6;
      ticks.push(['M', xv, y - half]);
      ticks.push(['L', xv, y + half]);
    }
    var dotA = visualSdk.circle(tx(1 / 3), y, 6);
    var dotB = visualSdk.circle(tx(1 / 2), y, 6);
    var labelY = y - 42;
    return {
      schemaVersion: 1,
      sceneId: 'numberline-third-half',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axis },
        { id: 'ticks', commands: ticks },
        { id: 'dotA', commands: dotA },
        { id: 'dotB', commands: dotB }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'axis', fill: main, stroke: { width: 2 } },
        { type: 'path', pathId: 'ticks', fill: main, stroke: { width: 2 } },
        { type: 'path', pathId: 'dotA', fill: accent, stroke: { width: 1 } },
        { type: 'path', pathId: 'dotB', fill: accent, stroke: { width: 1 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: x0, y: y + 18 }, hAlign: 'center', vAlign: 'top', color: main },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: x1, y: y + 18 }, hAlign: 'center', vAlign: 'top', color: main },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: tx(1 / 3), y: labelY }, hAlign: 'center', vAlign: 'bottom', color: accent },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: tx(1 / 2), y: labelY }, hAlign: 'center', vAlign: 'bottom', color: accent },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: W / 2, y: H - 30 }, hAlign: 'center', vAlign: 'middle', color: main }
      ] }
    };
  }
};
